package com.myaaptha.myaaptha_mobile
import android.Manifest;import android.content.pm.PackageManager;import android.provider.Telephony;import androidx.core.content.ContextCompat;import io.flutter.embedding.android.FlutterActivity;import io.flutter.embedding.engine.FlutterEngine;import io.flutter.plugin.common.MethodChannel
class MainActivity:FlutterActivity(){override fun configureFlutterEngine(engine:FlutterEngine){super.configureFlutterEngine(engine);MethodChannel(engine.dartExecutor.binaryMessenger,"myaaptha/sms").setMethodCallHandler{call,result->if(call.method!="financialMessages")result.notImplemented()else if(ContextCompat.checkSelfPermission(this,Manifest.permission.READ_SMS)!=PackageManager.PERMISSION_GRANTED)result.error("permission","SMS permission is required",null)else try{val output=mutableListOf<Map<String,Any?>>();contentResolver.query(Telephony.Sms.Inbox.CONTENT_URI,arrayOf(Telephony.Sms.ADDRESS,Telephony.Sms.BODY,Telephony.Sms.DATE),null,null,"${Telephony.Sms.DATE} DESC")?.use{cursor->val sender=cursor.getColumnIndex(Telephony.Sms.ADDRESS);val body=cursor.getColumnIndex(Telephony.Sms.BODY);val date=cursor.getColumnIndex(Telephony.Sms.DATE);while(cursor.moveToNext()&&output.size<200){val text=cursor.getString(body)?:"";if(Regex("(?i)(debited|credited|spent|purchase|transaction|withdrawn|received|₹|inr|rs\\.)").containsMatchIn(text))output.add(mapOf("sender" to cursor.getString(sender),"body" to text,"date" to cursor.getLong(date)))}};result.success(output)}catch(e:Exception){result.error("sms_read",e.message,null)}}}}
